import 'dart:io';

import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:nothingness/controllers/library_controller.dart';
import 'package:nothingness/models/audio_track.dart';
import 'package:nothingness/models/screen_config.dart';
import 'package:nothingness/models/song_info.dart';
import 'package:nothingness/models/spectrum_settings.dart';
import 'package:nothingness/screens/void_screen.dart';
import 'package:nothingness/services/library_browser.dart';
import 'package:nothingness/services/library_service.dart';
import 'package:nothingness/services/settings_service.dart';
import 'package:nothingness/theme/app_typography.dart';
import 'package:nothingness/widgets/heroes/_test_helpers.dart';
import 'package:nothingness/widgets/void_browser.dart';

import '../widgets/heroes/_test_helpers.dart';

class _RecordingLibraryController extends LibraryController {
  _RecordingLibraryController({
    super.currentPath,
    required super.tracks,
  }) : super(
          libraryBrowser: LibraryBrowser(supportedExtensions: const {'opus'}),
          libraryService: LibraryService(),
          isAndroidOverride: false,
        ) {
    hasPermission = true;
  }

  final List<String> loadFolderCalls = <String>[];

  @override
  Future<void> loadFolder(String path) async {
    loadFolderCalls.add(path);
    currentPath = path;
    notifyListeners();
  }
}

Future<void> _pump(
  WidgetTester tester,
  ScreenConfig config, {
  required LibraryController libraryController,
  required FakeAudioPlayerProvider provider,
  required double height,
}) async {
  await tester.binding.setSurfaceSize(const Size(800, 600));
  await tester.binding.setSurfaceSize(Size(800, height));

  await tester.pumpWidget(
    wrapWithProvider(
      provider,
      VoidScreen(
        config: config,
        settings: const SpectrumSettings(),
        libraryController: libraryController,
      ),
    ),
  );
  await tester.pump();
  await tester.pumpAndSettle();
}

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  setUp(() async {
    SettingsService().immersiveNotifier.value = false;
    SettingsService().transportPositionNotifier.value =
        TransportPosition.bottom;
  });

  testWidgets('a11y action appears when playing row is offscreen (Linux)',
      (tester) async {
    debugDefaultTargetPlatformOverride(TargetPlatform.linux);
    addTearDown(() => debugDefaultTargetPlatformOverride(null));

    const mediaDir = '/opt/nothingness/media';
    final files = <String>[
      '01-undercover-49.opus',
      '02-undercover-50.opus',
      '03-undercover-51.opus',
      '04-undercover-52.opus',
      '05-undercover-53.opus',
      '06-undercover-54.opus',
      '07-undercover-44.opus',
      '08-undercover-45.opus',
      '09-undercover-46.opus',
      '10-undercover-47.opus',
    ];

    final tracks = files
        .map(
          (f) => AudioTrack(
            path: '$mediaDir/$f',
            title: f.replaceAll('.opus', ''),
          ),
        )
        .toList(growable: false);

    // Choose a track near the end so it's likely offscreen in a short
    // viewport.
    final playing = tracks.last;

    final libraryController = _RecordingLibraryController(
      currentPath: mediaDir,
      tracks: tracks,
    );

    final provider = FakeAudioPlayerProvider(
      songInfo: SongInfo(
        track: playing,
        isPlaying: true,
        position: 0,
        duration: 1000,
      ),
    );

